(3961199, 547477, 3569, '<td valign="top">well over my head.</td>', 'well over my head.', '2007-08-02 10:32:40.000000', NULL, 1),
(3961221, 561425, 3697, '<td valign="top">I really like this one. The only thing that would have made it better is if the person''s arm wasn''t in the shot.</td>', 'I really like this one. The only thing that would have made it better is if the person''s arm wasn''t in the shot.', '2007-08-02 10:40:52.000000', NULL, 1),
(3961225, 563969, 3697, '<td valign="top">Absolutely beautiful shot!</td>', 'Absolutely beautiful shot!', '2007-08-02 10:41:48.000000', NULL, 1),
