(3962217, 557577, 81852, '<td valign="top">Wonderful detail and the lighting is perfect in my opinion. Good depth of field.</td>', 'Wonderful detail and the lighting is perfect in my opinion. Good depth of field.', '2007-08-02 15:34:45.000000', NULL, 1),
(3962256, 564379, 772, '<td valign="top">This is a beautiful sculpture... I never get tired of seeing it here :)</td>', 'This is a beautiful sculpture... I never get tired of seeing it here :)', '2007-08-02 15:46:47.000000', NULL, 1),
