(3962271, 556209, 81852, '<td valign="top">I like this. I feel like the shirt takes away from the intimacy.</td>', 'I like this. I feel like the shirt takes away from the intimacy.', '2007-08-02 15:53:26.000000', NULL, 1),
(3962285, 563691, 30049, '<td valign="top">Looks like a snapshot IMO.</td>', 'Looks like a snapshot IMO.', '2007-08-02 15:58:42.000000', NULL, 1),
(3962288, 564437, 81852, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2007-08-02 15:58:54.000000', NULL, 1),
