INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3970739, 564225, 42181, '<td valign="top">Superb sharp focus on the stamen</td>', 'Superb sharp focus on the stamen', '2007-08-05 14:06:43.000000', NULL, 1),
(3970745, 564623, 42181, '<td valign="top">IMO shame you weren''t able to remove the tree, it leads the eye out of the picture. Lovely waterfall shot though. 7</td>', 'IMO shame you weren''t able to remove the tree, it leads the eye out of the picture. Lovely waterfall shot though. 7', '2007-08-05 14:14:58.000000', NULL, 1),
(3970750, 562148, 41675, '<td valign="top">Its fun to look at water shots like this. Nice image, but for me, lacks that "wow" factor that makes me want to keep looking at it. I do like the sharpness of the water itself though.</td>', 'Its fun to look at water shots like this. Nice image, but for me, lacks that "wow" factor that makes me want to keep looking at it. I do like the sharpness of the water itself though.', '2007-08-05 14:20:53.000000', NULL, 1),
(3970751, 561680, 41675, '<td valign="top">The colors seem a bit over saturated and the highlights a little blown, but I do like the minimalist composition.</td>', 'The colors seem a bit over saturated and the highlights a little blown, but I do like the minimalist composition.', '2007-08-05 14:21:37.000000', NULL, 1),
(3970754, 562552, 41675, '<td valign="top">Very pretty photo. I especially like the light rays that draw my attention into your photo and down to the waterfall. Good eye.</td>', 'Very pretty photo. I especially like the light rays that draw my attention into your photo and down to the waterfall. Good eye.', '2007-08-05 14:23:08.000000', NULL, 1),
(3970755, 564093, 41675, '<td valign="top">Awww, this is so precious! Great black &amp; white contrast. What a wonderful image. 10</td>', 'Awww, this is so precious! Great black & white contrast. What a wonderful image. 10', '2007-08-05 14:23:49.000000', NULL, 1),
