(3975618, 562157, 18197, '<td valign="top">Wow!!!!! Toronto? Beautiful architectural shot. 10 from me.</td>', 'Wow!!!!! Toronto? Beautiful architectural shot. 10 from me.', '2007-08-06 23:40:45.000000', NULL, 1),
(3975621, 564549, 18197, '<td valign="top">Love it! Great detail ... and in your face!</td>', 'Love it! Great detail ... and in your face!', '2007-08-06 23:41:27.000000', NULL, 1),
