(3975630, 560625, 889, '<td valign="top">I think I would have cloned out the plane as an imperfection.</td>', 'I think I would have cloned out the plane as an imperfection.', '2007-08-06 23:44:34.000000', NULL, 1),
(3975632, 563969, 42100, '<td valign="top">Very vivid color...nicely done portrait!</td>', 'Very vivid color...nicely done portrait!', '2007-08-06 23:45:40.000000', NULL, 1),
(3975633, 563538, 18197, '<td valign="top">Nice composition but a bit overprocessed for my taste.</td>', 'Nice composition but a bit overprocessed for my taste.', '2007-08-06 23:45:42.000000', NULL, 1),
