(3975645, 564384, 18197, '<td valign="top">Love the old car. Well captured and presented.</td>', 'Love the old car. Well captured and presented.', '2007-08-06 23:47:29.000000', NULL, 1),
(3975648, 563616, 42100, '<td valign="top">That''s a lot of birds...great silhouettes with them and the cranes.  Very nice!</td>', 'That''s a lot of birds...great silhouettes with them and the cranes.  Very nice!', '2007-08-06 23:48:12.000000', NULL, 1),
